-- Code generated by factory from specs/receipts/list-top-line-stores/spec.yaml. DO NOT EDIT.

-- name: ListTopLineStores :many
SELECT t3.store_code, t3.total, t3.lines
FROM (
    SELECT t2.store_code AS store_code, t2.total AS total, t2.lines AS lines
    FROM (
        SELECT t1.store_code AS store_code, coalesce(sum(t1.amount), 0) AS total, count(*) AS lines
        FROM sales_lines AS t1
        WHERE (t1.sales_date = sqlc.arg(sales_date)::date)
        GROUP BY t1.store_code
    ) AS t2
) AS t3
ORDER BY t3.total DESC, t3.store_code
LIMIT 5;
